import blinker from "./examples/blinker.json"
import esp32Robot from "./examples/esp32-robot.json"
import mcu from "./examples/mcu.json"
import node from "./examples/node.json"
import regulator from "./examples/regulator.json"
import { registerProjectParts } from "./customParts"
import { TEMPLATES } from "./templates"
import type { Project } from "./types"

/**
 * The templates already built, routed and poured, so the dashboard shows and opens them at
 * once: routing the ESP32 robot takes seconds. Generated by `tests/templates.test.ts`, which
 * fails when one no longer matches a fresh build; `npm run examples`
 * rewrites them after a change to a template, a part or the router.
 */
const BUILT: Record<string, unknown> = { "esp32-robot": esp32Robot, node, blinker, regulator, mcu }

export interface Example {
  id: string
  name: string
  description: string
  project: Project
}

export const EXAMPLES: Example[] = TEMPLATES.map(({ id, name, description }) => ({ id, name, description, project: BUILT[id] as Project }))

// An example's chips are parts of its own, as a project's are, so they are registered with it: the
// dashboard draws an example's preview straight from it, without opening it.
for (const { project } of EXAMPLES) registerProjectParts(project)
